text:
{
  "claims": [
    {
      "anchor": "enable AOF on the live server with CONFIG SET appendonly yes",
      "claim_text": "To switch from RDB to AOF, enable AOF on the live server with CONFIG SET appendonly yes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P1.S0", "rel": "entails", "sub": "Enable AOF: `redis-cli config set appendonly yes`"}
      ],
      "check": null,
      "reasoning": "Both passages state enabling AOF via CONFIG on live server."
    },
    {
      "anchor": "also update redis.conf",
      "claim_text": "You must also update redis.conf when enabling AOF.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage says update redis.conf and ensure it matches."
    },
    {
      "anchor": "otherwise the change is lost when the server restarts",
      "claim_text": "If redis.conf is not updated, the configuration changes are lost on restart.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage states forgetting this step loses changes on restart."
    },
    {
      "anchor": "Redis automatically blocks incoming writes while it converts the dataset",
      "claim_text": "Redis automatically blocks incoming writes while converting the dataset.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions blocking writes during conversion."
    },
    {
      "anchor": "wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0",
      "claim_text": "Before restarting, wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"},
        {"sid": "P2.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage says wait for rewrite and watch both fields to be 0."
    },
    {
      "anchor": "On Redis 7.0 or later",
      "claim_text": "On Redis 7.0 or later, AOF files are split into multiple files.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "7.0", "op": ">=", "right": "7.0.0"},
      "reasoning": "Passage states since Redis 7.0.0 AOF files are split."
    },
    {
      "anchor": "an AOF-only instance can be backed up by copying the files in the directory",
      "claim_text": "An AOF-only instance can be backed up by copying the files in the AOF directory.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"},
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage says copy/tar files in directory to back up."
    },
    {
      "anchor": "set by the appendfilename option",
      "claim_text": "The AOF directory is set by the appendfilename option.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "refutes", "sub": "determined by the `appenddirname` configuration"}
      ],
      "check": null,
      "reasoning": "Passage says appenddirname, not appendfilename."
    },
    {
      "anchor": "copying them while a rewrite is running is safe",
      "claim_text": "Copying AOF files while a rewrite is running is safe.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S3", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says during rewrite you might get invalid backup."
    },
    {
      "anchor": "set auto-aof-rewrite-percentage to 0, which turns off automatic rewrites",
      "claim_text": "Setting auto-aof-rewrite-percentage to 0 turns off automatic rewrites.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S1", "rel": "entails", "sub": "Turn off automatic rewrites with<br/> `CONFIG SET` `auto-aof-rewrite-percentage 0`"}
      ],
      "check": null,
      "reasoning": "Passage states this turns off automatic rewrites."
    },
    {
      "anchor": "If you take hard links to those files, you can re-enable rewrites before the copy finishes",
      "claim_text": "If you take hard links to the files, you can re-enable rewrites before the copy finishes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"},
        {"sid": "P6.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage says create hard links then re-enable rewrites, then copy hardlinks."
    },
    {
      "anchor": "because Redis only appends to files in that directory or completely replaces them",
      "claim_text": "Redis only appends to files in the AOF directory or completely replaces them.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage states this guarantee."
    },
    {
      "anchor": "On Redis 6.0, backing up the AOF is as simple as copying the aof file",
      "claim_text": "On Redis 6.0, backing up the AOF is as simple as copying the aof file.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "6.0", "op": "<", "right": "7.0.0"},
      "reasoning": "Passage says prior to 7.0.0 copy aof file; 6.0 is prior."
    },
    {
      "anchor": "Redis can still load the copy even if it lacks the final part",
      "claim_text": "Redis can still load a copied AOF file even if it lacks the final part.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage states file may lack final part but Redis can load it."
    }
  ]
}
